<script lang="ts">import { onMount } from 'svelte';import Markdown from '../lib/Markdown.svelte'; export let id=''; export let onBack:()=>void=()=>{};let content:any=null;let error='';onMount(async()=>{try{const r=await fetch('/api/games/'+id+'/content');content=await r.json()}catch(e){error=(e as Error).message}});async function action(kind:string){const r=await fetch('/api/games/'+id+'/content/'+kind,{method:'POST'});if(!r.ok){error=(await r.json()).detail;return}onBack()}</script>
<section class="page"><a href={'/games/'+id} on:click|preventDefault={onBack}>← Game detail</a><h1>Review Draft Content</h1>{#if error}<p class="error">{error}</p>{/if}{#if content}<div class="columns"><article><h2>Quick-start Guide</h2><Markdown value={content.draft_quickstart_md||''}/></article><article><h2>Cheat Sheet</h2><Markdown value={content.draft_cheat_sheet_md||''}/></article></div><div class="actions"><button class="danger" on:click={()=>confirm('Reject this draft? You can regenerate after.')&&action('reject')}>Reject</button><button class="primary" on:click={()=>action('publish')}>Publish</button></div>{/if}</section>
<style>.page{padding:32px;max-width:1400px;margin:auto}.columns{display:grid;grid-template-columns:1fr 1fr;gap:24px}.columns article{padding:24px;background:#1e1c27;border:1px solid #29263c;min-height:400px}.actions{position:sticky;bottom:0;background:#1e1c27;padding:16px;display:flex;justify-content:space-between}.primary,.danger{padding:10px 24px;border-radius:10px}.primary{background:#a277ff;border:0}.danger{background:transparent;color:#ff6767;border:1px solid #ff676755}.error{color:#ff6767}@media(max-width:800px){.columns{grid-template-columns:1fr}.page{padding:20px}}</style>
